@Test
public void testCommandParser() throws Exception {
    try {
        CLIParser parser = new CLIParser("oozie", new String[] {});
        parser.addCommand("a", "<A>", "AAAAA", new Options(), false);
        CLIParser.Command c = parser.parse(new String[] { "a", "b" });
